"How strongly: subtle, or normal for a sharper voice.": "Наскільки сильно: м'яко або звично — для різкішого голосу.",
"Retune from 440 to 432 Hz (pitch and tempo together). Off keeps 440 Hz, for the public.": "Перестроїти з 440 на 432 Гц (висота й темп разом). Вимк.: 440 Гц, для публіки.",
"Brings the song to the loudness below: measured first, then set in a second pass. Off: the level stays as it came.": "Приводить пісню до гучності нижче: спершу замір, потім встановлення другим проходом. Вимк.: рівень лишається як був.",
"Loudness": "Гучність",
"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "Стеля для піків між відліками. −1 лишає місце кодерам MP3 й AAC, які додають власні піки.",
