"a new prompt, a new picture": "новий промпт, нова картинка",
"half a minute on a GPU": "пів хвилини на GPU",
"kept beside the take": "збережеться поруч із семплом",
"Regenerate with a new seed": "Перегенерувати з новим зерном",
"Regenerate {0} with new seeds": "Перегенерувати {0} з новими зернами",
"replaces it; the old one kept": "замінить його; старий збережеться",
"New section…": "Новий підрозділ…",
