"genres": "жанри",
"modes of major and minor": "лади мажору й мінору",
"found in the instrument probes": "знайдено в пробах інструментів",
"{0} styles · what a probe gave instead of its instrument": "Стилів: {0} · що проба дала замість свого інструмента",
"not judged yet": "ще не оцінено",
"no probe yet": "проби ще немає",
"✓ heard": "✓ почуто",
"The artwork: see it whole": "Обкладинка: подивитися цілком",
"Its picture: see it whole": "Картинка: подивитися цілком",
"On the cards now:": "Зараз на картах:",
"Drag to widen or narrow the workspaces; a double click folds them away": "Тягни, щоб розширити або звузити колонку просторів; подвійне клацання згортає її",
"Fold the workspaces away: the cards grow wider": "Згорнути простори: картки стануть ширшими",
