"Pin up to four takes of this place here: right-click a take → Pin here.": "Закріпи тут до чотирьох семплів цього місця: правою кнопкою по семплу → «Закріпити тут».",
"The workspaces column: drag to widen, Enter to fold": "Колонка просторів: тягни, щоб розширити, Enter — згорнути",
"four at most": "не більше чотирьох",
"Out of the studio": "Назовні зі студії",
"two ways: the mixed track as it is, or the whole take into your DAW, where the rest happens outside the studio": "два шляхи: зведений трек як є або весь семпл у твою DAW, де решта відбувається поза студією",
"The mixed track": "Зведений трек",
"As the studio made it (and the Refiner finished it), no DAW in between.": "Як його створила студія (і довершив Огранювач), без DAW посередині.",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Як його створила студія (і довершив Огранювач), без DAW посередині. Семпл у руках:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Відкрий семпл, увімкни його або познач у Бібліотекарі: його WAV, FLAC і MP3 з'являться тут.",
"Into your DAW": "У твою DAW",
"experimental": "експериментально",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "Воно діє й перевірене, але йому ще потрібні краш-тести на інших машинах і проєктах і доведення",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "Увесь семпл як проєкт твоєї DAW: стеми на своїх доріжках, партитура як MIDI, темп, розділи як регіони, текст на таймлайні. Якою DAW ти користуєшся?",
"Asking the lab…": "Питаємо лабораторію…",
"The lab does not answer: {0}": "Лабораторія не відповідає: {0}",
"✓ on the studio’s machine": "✓ на машині студії",
"✓ on the studio’s machine · {0}": "✓ на машині студії · {0}",
"not on the studio’s machine; on your own computer it may well be": "не на машині студії; на твоєму комп'ютері цілком може бути",
"How to install it": "Як установити",
"Your DAW ✓": "Твоя DAW ✓",
"I use this one": "Я користуюся цією",
"Export the take": "Експортувати семпл",
"A DAWproject: the mix, the stems, the score as notes, the sections as markers": "DAWproject: мікс, стеми, партитура нотами, розділи маркерами",
"first": "перша",
"next": "наступна",
"Now: the": "Зараз:",
"project (the mix, every stem, the score as MIDI; the lyrics and sections once the take is timed in the Refiner’s lyrics check), and": "— проєкт (мікс, кожен стем, партитура як MIDI; текст і розділи — коли семпл розмічено за часом у перевірці тексту в Огранювача), і",
"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(мікс, кожен стем, партитура нотами, розділи маркерами: Waveform 14, Bitwig, Studio One, Cubase); обидва є й у меню семплу → «Завантажити». Waveform: 14 або новіший.",
"Packing…": "Пакування…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 днів проби з усіма функціями, потім ліцензія: $60 для особистого користування або малого бізнесу",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 або новіший: безкоштовно, без обмежень на доріжки й експорт; відкриває DAWproject студії (File > Import Other > Import a DAWproject file). Waveform 13 не підтримується",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 днів без обмежень після реєстрації, потім Essentials $99, Producer $199 або Studio $399 (bitwig.com, 03.10.2026); відкриває DAWproject студії: мікс, стеми, партитура нотами, розділи маркерами",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php → архів Linux x86_64 → розпакуй і запусти ./install-reaper.sh (ставиться в /opt/REAPER)",
"tracktion.com/products/waveform-free → the .deb of Waveform 14 for Linux → sudo apt install ./waveform14_*.deb": "tracktion.com/products/waveform-free → .deb Waveform 14 для Linux → sudo apt install ./waveform14_*.deb",
"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download: .deb для Ubuntu (sudo apt install ./bitwig-studio-*.deb) або Flatpak",
