"It is the studio’s own card: a synthesis now would fight the training for its memory, and one of them would fail. The synthesis waits until the run ends, or until you stop it (Train). To create while training, give training another card: Engine → GPUs.": "Це власна карта студії: синтез зараз боровся б із тренуванням за її пам'ять, і хтось із них упав би. Синтез чекає, поки ран не закінчиться або поки ти його не зупиниш (Тренер). Щоб творити під час тренування, дай тренуванню іншу карту: Рушій → GPU.",
