"All the music strengths together. Measured on this studio's takes: the score came out whole up to {0} in every run, broken from 2.5 in every run. Green to {1}, amber to {2}, red past it.": "Усі музичні сили разом. Виміряно на семплах цієї студії: партитура виходила цілою до {0} у кожному запуску й зламаною від 2.5 у кожному. Зелений до {1}, жовтий до {2}, далі червоний.",
