"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} на музичній половині — вище її межі {2}: партитура зазвичай ламається після 70–200 токенів.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} на звуковій половині — вище її межі {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} планує інструментальні партитури: на {1} зі словами для співу партитура втрачає вокальну лінію (замір на 1.00: 1 нота на 127 вокальних тактів, музика зациклюється). Для пісні зі співом тримай низько, 0.3–0.5.",
"{#0} stacked: their changes add up.": "Накладено: {0}; їхні зміни додаються.",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ Музична половина несе разом {0}, вище спільної стелі {1}: такі важкі запуски щоразу писали зламані партитури (виміряно). Зменш якісь або зніми одну з музичної половини.",
