"How well the sound half predicts the noise it has to take away. Lower is better. It jumps from step to step with the random noise level of each step: read the bold line, the running average.": "Наскільки добре звукова половина передбачає шум, який їй треба прибрати. Нижче — краще. Скаче від кроку до кроку разом із випадковим рівнем шуму кожного кроку: читай жирну лінію, ковзне середнє.",
"How well the music half predicts the song’s own tokens. Lower is better; close to 0 it knows the songs by heart, and an earlier epoch is then the better adapter.": "Наскільки добре музична половина передбачає власні токени пісні. Нижче — краще; близько до 0 вона знає пісні напам'ять, і тоді кращий адаптер — раніша епоха.",
