"It takes a GPU of its own for hours; a set without its latent cache gets one first (a second or two a track).": "Він займає свою GPU на години; набір без латентного кешу спершу отримує його (секунда-дві на доріжку).",
"It takes a GPU of its own for hours; the first run also fetches Comfy-Org’s YuE2 weights.": "Він займає свою GPU на години; перший ран ще й завантажує ваги YuE2 від Comfy-Org.",
"Training may take GPU{0}, the studio’s own card: if it does, synthesis waits until the run ends (Engine → GPUs gives training another card).": "Тренування може зайняти GPU{0}, власну карту студії: тоді синтез чекає кінця рану (Рушій → GPU дасть тренуванню іншу карту).",
