"what a probe gave instead of its instrument": "що проба дала замість свого інструмента",
"Nothing matches.": "Нічого не підходить.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Ім'я в стилі — прохання, а не обіцянка. Те, що грають ▶ A і ▶ B, YuE2 дає на нього приблизно дев'ять разів із десяти.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Деякі проби чудові, A і B згодні, а інструмент не той, про який просили: вір вуху, а не імені.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Що YuE2 просили зіграти — по одному інструменту чи стилю, пробами по дві хвилини (перші — по хвилині), з двома сідами кожна, A і B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Інструмент ліпить стиль усієї речі: назвавши його, зсуваєш і аранжування. Тріск чи шурхіт паперу, як на заїждженій платівці, — невдалий сід: створи заново на іншому.",
