"Drag: the form takes 55 to 70 % of the width; below 55 the takes take 60 % and the form one column · double-click: the default": "Тягни: форма бере від 55 до 70 % ширини; нижче 55 семпли беруть 60 %, а форма стає в одну колонку · подвійне клацання — типово",
